// src/App.js
import React, { useState } from 'react';
import './App.css';

// --- IMPORT COMPONENT CŨ CỦA NGƯỜI 2 (GIỮ NGUYÊN 100% LOGIC) ---
import BudgetSetting from './components/BudgetSetting';
import DashboardChart from './components/DashboardChart';
import BudgetAlert from './components/BudgetAlert';

// --- IMPORT COMPONENT CỦA NGƯỜI 1 (GIẢ ĐỊNH ĐỂ RÁP NỐI UI) ---
// import TransactionForm from './components/TransactionForm';
// import TransactionList from './components/TransactionList';

// --- IMPORT CÁC COMPONENT TÍNH NĂNG MỚI (SẼ CODE Ở BƯỚC 3) ---
// import NetWorthSummary from './components/NetWorthSummary';
// import CashflowLineChart from './components/CashflowLineChart';
// import LoanManager from './components/LoanManager';
// import CreditDebtManager from './components/CreditDebtManager';
// import PiggyBank from './components/PiggyBank';
// import DataTransfer from './components/DataTransfer';
// import BackupHistory from './components/BackupHistory';
// import ThemeToggle from './components/ThemeToggle';
// import NotificationBell from './components/NotificationBell';

function App() {
  // State điều hướng Tabs (Chỉ phục vụ Layout UI, không ảnh hưởng logic nghiệp vụ)
  const [activeTab, setActiveTab] = useState('dashboard');

  return (
    <div className="app-container min-h-screen bg-gray-50 text-gray-800 flex flex-col md:flex-row transition-colors duration-300">

      {/* 1. SIDEBAR / NAVIGATION BAR */}
      <aside className="w-full md:w-64 bg-slate-900 text-white flex flex-col justify-between p-4 shadow-xl">
        <div>
          <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-700">
            <h1 className="text-xl font-bold tracking-wider text-emerald-400">💰 FINANCE PRO</h1>
            {/* [Tính năng mới 4] Nút đổi Theme Sáng/Tối/Hệ thống */}
            {/* <ThemeToggle /> */}
          </div>

          <nav className="flex flex-col space-y-2">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`p-3 rounded-lg text-left font-medium transition ${activeTab === 'dashboard' ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-slate-800 text-gray-300'}`}
            >
              📊 Tổng Quan & Biểu Đồ
            </button>
            <button 
              onClick={() => setActiveTab('transactions')}
              className={`p-3 rounded-lg text-left font-medium transition ${activeTab === 'transactions' ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-slate-800 text-gray-300'}`}
            >
              💸 Giao Dịch & Ngân Sách
            </button>
            <button 
              onClick={() => setActiveTab('loans')}
              className={`p-3 rounded-lg text-left font-medium transition ${activeTab === 'loans' ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-slate-800 text-gray-300'}`}
            >
